package com.aadil.ecommerce.repositories;import com.aadil.ecommerce.entities.ProductEntity;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;import java.util.Optional;@Repositorypublic interface ProductRepository extends JpaRepository<ProductEntity,Long> {   Page<ProductEntity> findByProductNameContainingIgnoreCaseOrDescriptionContainingIgnoreCase (String productName,String Description,Pageable pageable);}